var shortestPathLength = function(graph) {
    const n = graph.length;
    if (n <= 1) return 0;

    const fullMask = (1 << n) - 1;
    const queue = [];
    const seen = new Set();
    for (let node = 0; node < n; node++) {
        queue.push([node, 1 << node, 0]);
        seen.add(node * (1 << n) + (1 << node));
    }

    let head = 0;
    while (head < queue.length) {
        const [node, mask, distance] = queue[head++];
        for (const neighbor of graph[node]) {
            const nextMask = mask | (1 << neighbor);
            if (nextMask === fullMask) return distance + 1;
            const state = neighbor * (1 << n) + nextMask;
            if (!seen.has(state)) {
                seen.add(state);
                queue.push([neighbor, nextMask, distance + 1]);
            }
        }
    }

    return -1;
};

