from collections import deque
from typing import List

class Solution:
    def shortestPathLength(self, graph: List[List[int]]) -> int:
        n = len(graph)
        if n <= 1:
            return 0

        full_mask = (1 << n) - 1
        queue = deque((node, 1 << node, 0) for node in range(n))
        seen = {(node, 1 << node) for node in range(n)}

        while queue:
            node, mask, distance = queue.popleft()
            for neighbor in graph[node]:
                next_mask = mask | (1 << neighbor)
                if next_mask == full_mask:
                    return distance + 1
                state = (neighbor, next_mask)
                if state not in seen:
                    seen.add(state)
                    queue.append((neighbor, next_mask, distance + 1))

        return -1
